custom_css:
.web-form-container {
	max-width: 640px;
	margin: 2.5rem auto;
	padding: 0 1rem;
}
.web-form-header {
	background: #ffffff;
	border: 1px solid #e2e8f0;
	border-bottom: none;
	border-top-left-radius: 12px;
	border-top-right-radius: 12px;
	padding: 2rem 2rem 1.25rem 2rem;
	box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.04);
}
.web-form-head .web-form-title h1 {
	font-size: 1.5rem;
	font-weight: 700;
	color: #1e293b;
	margin-bottom: 0.35rem;
}
.web-form-introduction {
	font-size: 0.925rem;
	color: #64748b;
	line-height: 1.5;
}
.web-form {
	background: #ffffff;
	border: 1px solid #e2e8f0;
	border-top: none;
	border-bottom-left-radius: 12px;
	border-bottom-right-radius: 12px;
	padding: 0 2rem 2rem 2rem;
	box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.07), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}
.web-form .form-group {
	margin-bottom: 1.35rem;
}
.web-form .form-group label.control-label {
	font-weight: 600;
	font-size: 0.9rem;
	color: #334155;
	margin-bottom: 0.4rem;
	display: inline-block;
}
.web-form .form-control {
	border-radius: 8px;
	border: 1px solid #cbd5e1;
	padding: 0.65rem 0.85rem;
	font-size: 0.95rem;
	transition: border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out;
}
.web-form .form-control:focus {
	border-color: #3b82f6;
	box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
	outline: none;
}
.web-form-footer {
	margin-top: 1.5rem;
	padding-top: 1.5rem;
	border-top: 1px solid #f1f5f9;
}
.web-form-footer .btn-primary {
	border-radius: 8px;
	font-weight: 600;
	padding: 0.65rem 1.75rem;
	background-color: #2563eb;
	border-color: #2563eb;
}
.web-form-footer .btn-primary:hover {
	background-color: #1d4ed8;
	border-color: #1d4ed8;
}
@media (max-width: 768px) {
	.web-form-container {
		margin: 1rem auto;
		padding: 0 0.75rem;
	}
	.web-form-header {
		padding: 1.25rem 1.25rem 0.75rem 1.25rem;
		border-radius: 10px 10px 0 0;
	}
	.web-form-head .web-form-title h1 {
		font-size: 1.25rem;
	}
	.web-form {
		padding: 0 1.25rem 1.25rem 1.25rem;
		border-radius: 0 0 10px 10px;
	}
	.web-form-footer .web-form-actions {
		display: flex;
		flex-direction: column-reverse;
		gap: 0.75rem;
		width: 100%;
	}
	.web-form-footer .btn {
		width: 100%;
		margin-left: 0 !important;
		padding: 0.75rem 1rem;
		font-size: 1rem;
	}
}
